    idealAnswer: "**Custom hooks** are reusable functions that start with \"use\" and can call other hooks.\n\n**Creating a Custom Hook:**\n```jsx\n// Custom hook for localStorage\nfunction useLocalStorage(key, initialValue) {\n  // Get stored value or use initial value\n  const [storedValue, setStoredValue] = useState(() => {\n    try {\n      const item = window.localStorage.getItem(key);\n      return item ? JSON.parse(item) : initialValue;\n    } catch (error) {\n      return initialValue;\n    }\n  });\n  \n  // Update stored value\n  const setValue = (value) => {\n    try {\n      setStoredValue(value);\n      window.localStorage.setItem(key, JSON.stringify(value));\n    } catch (error) {\n      console.error(error);\n    }\n  };\n  \n  return [storedValue, setValue];\n}\n\n// Using the custom hook\nfunction App() {\n  const [name, setName] = useLocalStorage('name', 'John');\n  \n  return <input value={name} onChange={(e) => setName(e.target.value)} />;\n}\n```\n\n**More Examples:**\n\n**API Data Fetching Hook:**\n```jsx\nfunction useApi(url) {\n  const [data, setData] = useState(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState(null);\n  \n  useEffect(() => {\n    let cancelled = false;\n    \n    const fetchData = async () => {\n      try {\n        setLoading(true);\n        const response = await fetch(url);\n        const result = await response.json();\n        \n        if (!cancelled) {\n          setData(result);\n          setError(null);\n        }\n      } catch (err) {\n        if (!cancelled) {\n          setError(err.message);\n        }\n      } finally {\n        if (!cancelled) {\n          setLoading(false);\n        }\n      }\n    };\n    \n    fetchData();\n    \n    return () => { cancelled = true; };\n  }, [url]);\n  \n  return { data, loading, error };\n}\n```\n\n**Window Size Hook:**\n```jsx\nfunction useWindowSize() {\n  const [windowSize, setWindowSize] = useState({\n    width: window.innerWidth,\n    height: window.innerHeight\n  });\n  \n  useEffect(() => {\n    const handleResize = () => {\n      setWindowSize({\n        width: window.innerWidth,\n        height: window.innerHeight\n      });\n    };\n    \n    window.addEventListener('resize', handleResize);\n    return () => window.removeEventListener('resize', handleResize);\n  }, []);\n  \n  return windowSize;\n}\n```\n\n**Custom Hook Rules:**\n1. Must start with \"use\"\n2. Can call other hooks\n3. Share stateful logic, not UI\n4. Can be used in components and other hooks\n\n**Benefits:**\n- Reusability: Share logic between components\n- Separation of concerns: Logic separate from UI\n- Testability: Test hooks independently\n- Composition: Combine multiple hooks"
