    question: "What are Higher-Order Components (HOCs)?",
    idealAnswer: "**Higher-Order Components (HOCs)** are functions that take a component and return a new component with additional props or behavior.\n\n**Basic HOC Pattern:**\n```jsx\nfunction withLogging(WrappedComponent) {\n  return function WithLoggingComponent(props) {\n    console.log('Rendering:', WrappedComponent.name);\n    return <WrappedComponent {...props} />;\n  };\n}\n\n// Usage\nconst EnhancedComponent = withLogging(MyComponent);\n```\n\n**Real-World Examples:**\n\n**1. Data Fetching HOC:**\n```jsx\nfunction withData(WrappedComponent, url) {\n  return function WithDataComponent(props) {\n    const [data, setData] = useState(null);\n    const [loading, setLoading] = useState(true);\n    \n    useEffect(() => {\n      fetch(url)\n        .then(res => res.json())\n        .then(data => {\n          setData(data);\n          setLoading(false);\n        });\n    }, []);\n    \n    if (loading) return <div>Loading...</div>;\n    \n    return <WrappedComponent {...props} data={data} />;\n  };\n}\n\n// Usage\nconst UserProfileWithData = withData(UserProfile, '/api/user');\n```\n\n**2. Authentication HOC:**\n```jsx\nfunction withAuth(WrappedComponent) {\n  return function WithAuthComponent(props) {\n    const [user, setUser] = useState(null);\n    \n    useEffect(() => {\n      // Check authentication\n      const token = localStorage.getItem('token');\n      if (token) {\n        // Validate token and set user\n        setUser({ name: 'John Doe' });\n      }\n    }, []);\n    \n    if (!user) {\n      return <div>Please log in</div>;\n    }\n    \n    return <WrappedComponent {...props} user={user} />;\n  };\n}\n\n// Usage\nconst ProtectedComponent = withAuth(Dashboard);\n```\n\n**3. Styling HOC:**\n```jsx\nfunction withStyles(WrappedComponent, styles) {\n  return function WithStylesComponent(props) {\n    return (\n      <div style={styles}>\n        <WrappedComponent {...props} />\n      </div>\n    );\n  };\n}\n\n// Usage\nconst StyledButton = withStyles(Button, {\n  backgroundColor: 'blue',\n  color: 'white',\n  padding: '10px'\n});\n```\n\n**HOC Composition:**\n```jsx\n// Compose multiple HOCs\nconst EnhancedComponent = withAuth(\n  withData(\n    withStyles(UserProfile, userStyles),\n    '/api/user'\n  )\n);\n```\n\n**Best Practices:**\n- Don't modify the original component\n- Pass through unrelated props\n- Use composition over inheritance\n- Consider custom hooks as an alternative\n\n**HOCs vs Hooks:**\n- HOCs: Component enhancement pattern\n- Hooks: Logic reuse pattern\n- Modern React prefers hooks for most use cases"
