    question: "Implement a custom useLocalStorage hook that persists state to localStorage",
    idealAnswer: "**useLocalStorage Hook Implementation:**\n\n```jsx\nimport { useState, useEffect } from 'react';\n\nfunction useLocalStorage(key, initialValue) {\n  // Get stored value from localStorage or use initialValue\n  const [storedValue, setStoredValue] = useState(() => {\n    try {\n      const item = window.localStorage.getItem(key);\n      return item ? JSON.parse(item) : initialValue;\n    } catch (error) {\n      console.error(`Error reading localStorage key \"${key}\":`, error);\n      return initialValue;\n    }\n  });\n\n  // Update localStorage when state changes\n  const setValue = (value) => {\n    try {\n      // Allow value to be a function (like useState)\n      const valueToStore = value instanceof Function ? value(storedValue) : value;\n      setStoredValue(valueToStore);\n      window.localStorage.setItem(key, JSON.stringify(valueToStore));\n    } catch (error) {\n      console.error(`Error setting localStorage key \"${key}\":`, error);\n    }\n  };\n\n  return [storedValue, setValue];\n}\n\n// Usage example\nfunction App() {\n  const [name, setName] = useLocalStorage('name', 'John');\n  const [age, setAge] = useLocalStorage('age', 25);\n  \n  return (\n    <div>\n      <input \n        value={name} \n        onChange={(e) => setName(e.target.value)}\n        placeholder=\"Name\"\n      />\n      <input \n        type=\"number\"\n        value={age} \n        onChange={(e) => setAge(Number(e.target.value))}\n        placeholder=\"Age\"\n      />\n    </div>\n  );\n}\n```\n\n**Key Features:**\n- **SSR Safe**: Handles server-side rendering errors\n- **Function Support**: Like useState, accepts function updates\n- **Error Handling**: Graceful fallback on localStorage errors\n- **Type Safety**: Works with any JSON-serializable value"
