    question: "Implement a debounce hook for search inputs",
    idealAnswer: "**useDebounce Hook Implementation:**\n\n```jsx\nimport { useState, useEffect } from 'react';\n\nfunction useDebounce(value, delay) {\n  const [debouncedValue, setDebouncedValue] = useState(value);\n\n  useEffect(() => {\n    const handler = setTimeout(() => {\n      setDebouncedValue(value);\n    }, delay);\n\n    return () => {\n      clearTimeout(handler);\n    };\n  }, [value, delay]);\n\n  return debouncedValue;\n}\n\n// Usage example for search\nfunction SearchComponent() {\n  const [searchTerm, setSearchTerm] = useState('');\n  const debouncedSearchTerm = useDebounce(searchTerm, 500);\n  const [results, setResults] = useState([]);\n\n  useEffect(() => {\n    if (debouncedSearchTerm) {\n      // Make API call only when debounced value changes\n      searchAPI(debouncedSearchTerm).then(setResults);\n    } else {\n      setResults([]);\n    }\n  }, [debouncedSearchTerm]);\n\n  return (\n    <div>\n      <input\n        type=\"text\"\n        value={searchTerm}\n        onChange={(e) => setSearchTerm(e.target.value)}\n        placeholder=\"Search...\"\n      />\n      <ul>\n        {results.map(item => (\n          <li key={item.id}>{item.name}</li>\n        ))}\n      </ul>\n    </div>\n  );\n}\n```\n\n**Advanced Version with Options:**\n```jsx\nfunction useDebounce(value, delay, options = {}) {\n  const [debouncedValue, setDebouncedValue] = useState(value);\n  const { leading = false, trailing = true } = options;\n\n  useEffect(() => {\n    let timeoutId;\n    let calledLeading = false;\n\n    const callFunction = () => {\n      setDebouncedValue(value);\n    };\n\n    if (leading && !calledLeading) {\n      callFunction();\n      calledLeading = true;\n    }\n\n    if (trailing) {\n      timeoutId = setTimeout(callFunction, delay);\n    }\n\n    return () => {\n      if (timeoutId) {\n        clearTimeout(timeoutId);\n      }\n    };\n  }, [value, delay, leading, trailing]);\n\n  return debouncedValue;\n}\n```"
