    question: "Build a reusable Form component with validation",
    idealAnswer: "**Reusable Form Component:**\n\n```jsx\nimport { useState, createContext, useContext } from 'react';\n\n// Form context\nconst FormContext = createContext();\n\nfunction Form({ children, onSubmit, initialValues = {} }) {\n  const [values, setValues] = useState(initialValues);\n  const [errors, setErrors] = useState({});\n  const [touched, setTouched] = useState({});\n\n  const setValue = (name, value) => {\n    setValues(prev => ({ ...prev, [name]: value }));\n  };\n\n  const setError = (name, error) => {\n    setErrors(prev => ({ ...prev, [name]: error }));\n  };\n\n  const setTouched = (name) => {\n    setTouched(prev => ({ ...prev, [name]: true }));\n  };\n\n  const handleSubmit = (e) => {\n    e.preventDefault();\n    const result = onSubmit(values);\n    if (result && result.errors) {\n      setErrors(result.errors);\n    }\n  };\n\n  return (\n    <FormContext.Provider value={{\n      values,\n      errors,\n      touched,\n      setValue,\n      setError,\n      setTouched\n    }}>\n      <form onSubmit={handleSubmit}>\n        {children}\n      </form>\n    </FormContext.Provider>\n  );\n}\n\n// Form field component\nfunction Field({ name, label, validate, component: Component = 'input', ...props }) {\n  const { values, errors, touched, setValue, setError, setTouched } = useContext(FormContext);\n  const value = values[name] || '';\n  const error = touched[name] && errors[name];\n\n  const handleChange = (e) => {\n    const newValue = e.target.value;\n    setValue(name, newValue);\n    \n    if (validate && touched[name]) {\n      const validationError = validate(newValue);\n      setError(name, validationError);\n    }\n  };\n\n  const handleBlur = () => {\n    setTouched(name);\n    if (validate) {\n      const validationError = validate(value);\n      setError(name, validationError);\n    }\n  };\n\n  return (\n    <div className=\"field\">\n      {label && <label>{label}</label>}\n      <Component\n        value={value}\n        onChange={handleChange}\n        onBlur={handleBlur}\n        {...props}\n      />\n      {error && <span className=\"error\">{error}</span>}\n    </div>\n  );\n}\n\n// Usage example\nfunction UserForm() {\n  const validateEmail = (email) => {\n    if (!email) return 'Email is required';\n    if (!/\\S+@\\S+\\.\\S+/.test(email)) return 'Email is invalid';\n    return '';\n  };\n\n  const validatePassword = (password) => {\n    if (!password) return 'Password is required';\n    if (password.length < 6) return 'Password must be at least 6 characters';\n    return '';\n  };\n\n  const handleSubmit = (values) => {\n    const errors = {};\n    \n    const emailError = validateEmail(values.email);\n    if (emailError) errors.email = emailError;\n    \n    const passwordError = validatePassword(values.password);\n    if (passwordError) errors.password = passwordError;\n    \n    if (Object.keys(errors).length > 0) {\n      return { errors };\n    }\n    \n    // Submit form\n    console.log('Form submitted:', values);\n  };\n\n  return (\n    <Form onSubmit={handleSubmit}>\n      <Field\n        name=\"email\"\n        label=\"Email\"\n        type=\"email\"\n        validate={validateEmail}\n      />\n      <Field\n        name=\"password\"\n        label=\"Password\"\n        type=\"password\"\n        validate={validatePassword}\n      />\n      <button type=\"submit\">Submit</button>\n    </Form>\n  );\n}\n```"
