    question: "Implement a virtual scrolling component for large lists",
    idealAnswer: "**Virtual Scrolling Implementation:**\n\n```jsx\nimport { useState, useEffect, useRef, useMemo } from 'react';\n\nfunction VirtualList({ items, itemHeight = 50, containerHeight = 400, renderItem }) {\n  const [scrollTop, setScrollTop] = useState(0);\n  const containerRef = useRef(null);\n\n  const visibleStart = Math.floor(scrollTop / itemHeight);\n  const visibleEnd = Math.min(\n    visibleStart + Math.ceil(containerHeight / itemHeight) + 1,\n    items.length - 1\n  );\n\n  const visibleItems = useMemo(() => {\n    return items.slice(visibleStart, visibleEnd + 1);\n  }, [items, visibleStart, visibleEnd]);\n\n  const totalHeight = items.length * itemHeight;\n  const offsetY = visibleStart * itemHeight;\n\n  const handleScroll = (e) => {\n    setScrollTop(e.target.scrollTop);\n  };\n\n  return (\n    <div\n      ref={containerRef}\n      style={{\n        height: containerHeight,\n        overflow: 'auto',\n        border: '1px solid #ccc'\n      }}\n      onScroll={handleScroll}\n    >\n      <div style={{ height: totalHeight, position: 'relative' }}>\n        <div style={{ transform: `translateY(${offsetY}px)` }}>\n          {visibleItems.map((item, index) => (\n            <div\n              key={visibleStart + index}\n              style={{\n                height: itemHeight,\n                boxSizing: 'border-box',\n                borderBottom: '1px solid #eee'\n              }}\n            >\n              {renderItem(item, visibleStart + index)}\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  );\n}\n\n// Usage example\nfunction LargeDataList() {\n  const items = Array.from({ length: 10000 }, (_, i) => ({\n    id: i,\n    name: `Item ${i}`,\n    description: `Description for item ${i}`\n  }));\n\n  const renderItem = (item, index) => (\n    <div style={{ padding: '10px' }}>\n      <strong>{item.name}</strong> - {item.description}\n    </div>\n  );\n\n  return (\n    <div>\n      <h2>Virtual List (10,000 items)</h2>\n      <VirtualList\n        items={items}\n        itemHeight={60}\n        containerHeight={400}\n        renderItem={renderItem}\n      />\n    </div>\n  );\n}\n```\n\n**Advanced Version with Dynamic Heights:**\n```jsx\nfunction DynamicVirtualList({ items, containerHeight, renderItem }) {\n  const [scrollTop, setScrollTop] = useState(0);\n  const [itemHeights, setItemHeights] = useState(new Map());\n  const containerRef = useRef(null);\n  const itemRefs = useRef(new Map());\n\n  const getItemHeight = (index) => {\n    return itemHeights.get(index) || 50; // Default height\n  };\n\n  const getItemOffset = (index) => {\n    let offset = 0;\n    for (let i = 0; i < index; i++) {\n      offset += getItemHeight(i);\n    }\n    return offset;\n  };\n\n  const findVisibleRange = () => {\n    let start = 0;\n    let end = items.length - 1;\n    let currentOffset = 0;\n\n    // Find start index\n    for (let i = 0; i < items.length; i++) {\n      const itemHeight = getItemHeight(i);\n      if (currentOffset + itemHeight > scrollTop) {\n        start = i;\n        break;\n      }\n      currentOffset += itemHeight;\n    }\n\n    // Find end index\n    currentOffset = getItemOffset(start);\n    for (let i = start; i < items.length; i++) {\n      currentOffset += getItemHeight(i);\n      if (currentOffset > scrollTop + containerHeight) {\n        end = i;\n        break;\n      }\n    }\n\n    return { start, end };\n  };\n\n  const { start, end } = findVisibleRange();\n  const visibleItems = items.slice(start, end + 1);\n\n  const handleItemResize = (index, height) => {\n    setItemHeights(prev => new Map(prev).set(index, height));\n  };\n\n  return (\n    <div\n      ref={containerRef}\n      style={{ height: containerHeight, overflow: 'auto' }}\n      onScroll={(e) => setScrollTop(e.target.scrollTop)}\n    >\n      <div style={{ height: getItemOffset(items.length) }}>\n        {visibleItems.map((item, index) => (\n          <VirtualItem\n            key={start + index}\n            index={start + index}\n            offset={getItemOffset(start + index)}\n            onResize={handleItemResize}\n          >\n            {renderItem(item, start + index)}\n          </VirtualItem>\n        ))}\n      </div>\n    </div>\n  );\n}\n```"
