    question: "Implement an infinite scroll component with loading states",
    idealAnswer: "**Infinite Scroll Implementation:**\n\n```jsx\nimport { useState, useEffect, useRef, useCallback } from 'react';\n\nfunction useInfiniteScroll(fetchMore, hasMore) {\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState(null);\n  const observerRef = useRef();\n  const loadMoreRef = useRef();\n\n  const lastElementRef = useCallback(\n    (node) => {\n      if (loading) return;\n      if (observerRef.current) observerRef.current.disconnect();\n      \n      observerRef.current = new IntersectionObserver(\n        (entries) => {\n          if (entries[0].isIntersecting && hasMore && !loading) {\n            loadMoreRef.current();\n          }\n        },\n        { threshold: 1.0 }\n      );\n      \n      if (node) observerRef.current.observe(node);\n    },\n    [loading, hasMore]\n  );\n\n  const loadMore = useCallback(async () => {\n    if (!hasMore || loading) return;\n    \n    setLoading(true);\n    setError(null);\n    \n    try {\n      await fetchMore();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoading(false);\n    }\n  }, [fetchMore, hasMore, loading]);\n\n  loadMoreRef.current = loadMore;\n\n  return { lastElementRef, loading, error, loadMore };\n}\n\n// Infinite Scroll Component\nfunction InfiniteScrollList({ fetchData, renderItem }) {\n  const [items, setItems] = useState([]);\n  const [page, setPage] = useState(1);\n  const [hasMore, setHasMore] = useState(true);\n\n  const fetchMore = async () => {\n    const newItems = await fetchData(page);\n    \n    if (newItems.length === 0) {\n      setHasMore(false);\n    } else {\n      setItems(prev => [...prev, ...newItems]);\n      setPage(prev => prev + 1);\n    }\n  };\n\n  const { lastElementRef, loading, error } = useInfiniteScroll(fetchMore, hasMore);\n\n  // Initial load\n  useEffect(() => {\n    fetchMore();\n  }, []);\n\n  return (\n    <div>\n      <div>\n        {items.map((item, index) => (\n          <div\n            key={item.id || index}\n            ref={index === items.length - 1 ? lastElementRef : null}\n          >\n            {renderItem(item, index)}\n          </div>\n        ))}\n      </div>\n      \n      {loading && (\n        <div style={{ padding: '20px', textAlign: 'center' }}>\n          <div>Loading more items...</div>\n        </div>\n      )}\n      \n      {error && (\n        <div style={{ padding: '20px', textAlign: 'center', color: 'red' }}>\n          <div>Error: {error}</div>\n          <button onClick={() => fetchMore()}>Retry</button>\n        </div>\n      )}\n      \n      {!hasMore && items.length > 0 && (\n        <div style={{ padding: '20px', textAlign: 'center', color: '#666' }}>\n          No more items to load\n        </div>\n      )}\n    </div>\n  );\n}\n\n// Usage example\nfunction App() {\n  const fetchItems = async (page) => {\n    const response = await fetch(`https://jsonplaceholder.typicode.com/posts?_page=${page}&_limit=10`);\n    const items = await response.json();\n    return items;\n  };\n\n  const renderItem = (item) => (\n    <div style={{\n      padding: '15px',\n      border: '1px solid #ddd',\n      margin: '10px 0',\n      borderRadius: '5px'\n    }}>\n      <h3>{item.title}</h3>\n      <p>{item.body}</p>\n    </div>\n  );\n\n  return (\n    <div style={{ maxWidth: '600px', margin: '0 auto' }}>\n      <h1>Infinite Scroll Posts</h1>\n      <InfiniteScrollList\n        fetchData={fetchItems}\n        renderItem={renderItem}\n      />\n    </div>\n  );\n}\n```\n\n**With Manual Load More Button:**\n```jsx\nfunction InfiniteScrollWithButton({ fetchData, renderItem }) {\n  const [items, setItems] = useState([]);\n  const [loading, setLoading] = useState(false);\n  const [page, setPage] = useState(1);\n  const [hasMore, setHasMore] = useState(true);\n\n  const loadMore = async () => {\n    setLoading(true);\n    try {\n      const newItems = await fetchData(page);\n      \n      if (newItems.length === 0) {\n        setHasMore(false);\n      } else {\n        setItems(prev => [...prev, ...newItems]);\n        setPage(prev => prev + 1);\n      }\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <div>\n      {items.map((item, index) => (\n        <div key={item.id || index}>\n          {renderItem(item, index)}\n        </div>\n      ))}\n      \n      {hasMore && (\n        <div style={{ textAlign: 'center', padding: '20px' }}>\n          <button\n            onClick={loadMore}\n            disabled={loading}\n            style={{\n              padding: '10px 20px',\n              fontSize: '16px',\n              cursor: loading ? 'not-allowed' : 'pointer',\n              opacity: loading ? 0.7 : 1\n            }}\n          >\n            {loading ? 'Loading...' : 'Load More'}\n          </button>\n        </div>\n      )}\n    </div>\n  );\n}\n```"
