    question: "Build a data table component with sorting, filtering, and pagination",
    idealAnswer: "**Advanced Data Table Component:**\n\n```jsx\nimport { useState, useEffect, useMemo } from 'react';\n\nfunction DataTable({ data, columns, itemsPerPage = 10 }) {\n  const [currentPage, setCurrentPage] = useState(1);\n  const [sortConfig, setSortConfig] = useState({ key: null, direction: 'asc' });\n  const [filters, setFilters] = useState({});\n\n  // Handle sorting\n  const handleSort = (key) => {\n    setSortConfig(prev => ({\n      key,\n      direction: prev.key === key && prev.direction === 'asc' ? 'desc' : 'asc'\n    }));\n  };\n\n  // Handle filtering\n  const handleFilter = (key, value) => {\n    setFilters(prev => ({\n      ...prev,\n      [key]: value\n    }));\n    setCurrentPage(1); // Reset to first page when filtering\n  };\n\n  // Filter and sort data\n  const processedData = useMemo(() => {\n    let filtered = [...data];\n\n    // Apply filters\n    Object.entries(filters).forEach(([key, value]) => {\n      if (value) {\n        filtered = filtered.filter(item =>\n          String(item[key]).toLowerCase().includes(value.toLowerCase())\n        );\n      }\n    });\n\n    // Apply sorting\n    if (sortConfig.key) {\n      filtered.sort((a, b) => {\n        const aValue = a[sortConfig.key];\n        const bValue = b[sortConfig.key];\n        \n        if (aValue < bValue) {\n          return sortConfig.direction === 'asc' ? -1 : 1;\n        }\n        if (aValue > bValue) {\n          return sortConfig.direction === 'asc' ? 1 : -1;\n        }\n        return 0;\n      });\n    }\n\n    return filtered;\n  }, [data, filters, sortConfig]);\n\n  // Pagination\n  const totalPages = Math.ceil(processedData.length / itemsPerPage);\n  const startIndex = (currentPage - 1) * itemsPerPage;\n  const endIndex = startIndex + itemsPerPage;\n  const paginatedData = processedData.slice(startIndex, endIndex);\n\n  const goToPage = (page) => {\n    setCurrentPage(Math.max(1, Math.min(page, totalPages)));\n  };\n\n  return (\n    <div className=\"data-table\">\n      {/* Filters */}\n      <div className=\"table-filters\">\n        {columns.map(column => (\n          column.filterable && (\n            <input\n              key={column.key}\n              type=\"text\"\n              placeholder={`Filter by ${column.title}`}\n              value={filters[column.key] || ''}\n              onChange={(e) => handleFilter(column.key, e.target.value)}\n              style={{ margin: '5px', padding: '5px' }}\n            />\n          )\n        ))}\n      </div>\n\n      {/* Table */}\n      <table style={{ width: '100%', borderCollapse: 'collapse' }}>\n        <thead>\n          <tr style={{ backgroundColor: '#f5f5f5' }}>\n            {columns.map(column => (\n              <th\n                key={column.key}\n                onClick={() => column.sortable && handleSort(column.key)}\n                style={{\n                  padding: '10px',\n                  textAlign: 'left',\n                  border: '1px solid #ddd',\n                  cursor: column.sortable ? 'pointer' : 'default'\n                }}\n              >\n                {column.title}\n                {sortConfig.key === column.key && (\n                  <span>{sortConfig.direction === 'asc' ? ' ↑' : ' ↓'}</span>\n                )}\n              </th>\n            ))}\n          </tr>\n        </thead>\n        <tbody>\n          {paginatedData.map((row, index) => (\n            <tr key={row.id || index} style={{ backgroundColor: index % 2 === 0 ? '#fff' : '#f9f9f9' }}>\n              {columns.map(column => (\n                <td key={column.key} style={{ padding: '10px', border: '1px solid #ddd' }}>\n                  {column.render ? column.render(row[column.key], row) : row[column.key]}\n                </td>\n              ))}\n            </tr>\n          ))}\n        </tbody>\n      </table>\n\n      {/* Pagination */}\n      <div className=\"table-pagination\" style={{ marginTop: '20px', textAlign: 'center' }}>\n        <button\n          onClick={() => goToPage(currentPage - 1)}\n          disabled={currentPage === 1}\n          style={{ margin: '0 5px', padding: '5px 10px' }}\n        >\n          Previous\n        </button>\n        \n        <span style={{ margin: '0 10px' }}>\n          Page {currentPage} of {totalPages} ({processedData.length} items)\n        </span>\n        \n        <button\n          onClick={() => goToPage(currentPage + 1)}\n          disabled={currentPage === totalPages}\n          style={{ margin: '0 5px', padding: '5px 10px' }}\n        >\n          Next\n        </button>\n      </div>\n    </div>\n  );\n}\n\n// Usage example\nfunction App() {\n  const data = [\n    { id: 1, name: 'John Doe', age: 30, city: 'New York', salary: 50000 },\n    { id: 2, name: 'Jane Smith', age: 25, city: 'Los Angeles', salary: 60000 },\n    { id: 3, name: 'Bob Johnson', age: 35, city: 'Chicago', salary: 55000 },\n    // ... more data\n  ];\n\n  const columns = [\n    {\n      key: 'name',\n      title: 'Name',\n      sortable: true,\n      filterable: true\n    },\n    {\n      key: 'age',\n      title: 'Age',\n      sortable: true,\n      filterable: true\n    },\n    {\n      key: 'city',\n      title: 'City',\n      sortable: true,\n      filterable: true\n    },\n    {\n      key: 'salary',\n      title: 'Salary',\n      sortable: true,\n      filterable: true,\n      render: (value) => `$${value.toLocaleString()}`\n    }\n  ];\n\n  return (\n    <div style={{ padding: '20px' }}>\n      <h1>Employee Data Table</h1>\n      <DataTable data={data} columns={columns} itemsPerPage={5} />\n    </div>\n  );\n}\n```"
